import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    moves = [int(x) for x in data[1:1 + n]]
    grid = [[' '] * 7 for _ in range(6)]
    height = [0] * 7

    def wins(r, c, tok):
        for dr, dc in ((0, 1), (1, 0), (1, 1), (1, -1)):
            cnt = 1
            for s in (1, -1):
                rr, cc = r + s * dr, c + s * dc
                while 0 <= rr < 6 and 0 <= cc < 7 and grid[rr][cc] == tok:
                    cnt += 1
                    rr += s * dr
                    cc += s * dc
            if cnt >= 4:
                return True
        return False

    for k, c in enumerate(moves):
        if c < 0 or c > 6 or height[c] == 6:
            break
        tok = '0' if k % 2 == 0 else 'X'
        r = 5 - height[c]
        height[c] += 1
        grid[r][c] = tok
        if wins(r, c, tok):
            break
    for row in grid:
        print('|' + '|'.join(row) + '|')

main()

