cols = [[] for _ in range(7)]

def cell(r, c):
    # r = 0 is the bottom row
    if 0 <= c < 7 and 0 <= r < len(cols[c]):
        return cols[c][r]
    return ' '

def any_four():
    for r in range(6):
        for c in range(7):
            t = cell(r, c)
            if t == ' ':
                continue
            for dr, dc in ((0, 1), (1, 0), (1, 1), (1, -1)):
                if all(cell(r + k * dr, c + k * dc) == t for k in range(4)):
                    return True
    return False

turn = 0
for m in moves:
    if m < 0 or m > 6 or len(cols[m]) >= 6:
        break
    cols[m].append('0' if turn % 2 == 0 else 'X')
    turn += 1
